// Ref: #/components/schemas/RiskScenario
type RiskScenario struct {
	// The unique ID of the risk specified by the user. Used to reference and update existing risks.
	RiskId string `json:"riskId"`
	// This describes an actual or potential risk to your organization's people, processes, technology,
	// data, and facilities.
	// Document actual issues or likely scenarios based on your specific environment or a potential
	// vulnerability.
	Description string `json:"description"`
	// If set to true this risk can only be seen by its owner or users with Admin, RiskSensitiveManage or
	// RiskSensitiveView permissions.
	//
	// Deprecated: schema marks this property as deprecated.
	IsSensitive NilBool `json:"isSensitive"`
	// Represents the probability of an incident occurring due to this risk or vulnerability, expressed
	// as a numerical score.
	// Defaults to a range of 1-5, where higher values indicate greater likelihood. The range can be
	// customized in the Risk Management settings.
	// A value of `null` indicates that no score has been assigned.
	Likelihood NilFloat64 `json:"likelihood"`
	// Represents the potential severity of harm to your organization’s operations if this risk is
	// exploited, expressed as a numerical score.
	// Defaults to a range of 1-5, where higher values indicate greater impact. The range can be
	// customized in the Risk Management settings.
	// A value of `null` indicates that no score has been assigned.
	Impact NilFloat64 `json:"impact"`
	// Represents the adjusted probability of this risk being exploited or affecting operations after
	// implementing risk treatments, such as controls or mitigations.
	// Expressed as a numerical score, defaulting to a range of 1-5. The range can be customized in the
	// Risk Management settings.
	// A value of `null` indicates that no score has been assigned.
	ResidualLikelihood NilFloat64 `json:"residualLikelihood"`
	// Represents the adjusted severity of harm to your organization’s operations if this risk is
	// exploited after implementing risk treatments, such as controls or mitigations.
	// Expressed as a numerical score, defaulting to a range of 1-5. The range can be customized in the
	// Risk Management settings.
	// A value of `null` indicates that no score has been assigned.
	ResidualImpact NilFloat64 `json:"residualImpact"`
	// The list of categories this risk scenario belongs to.
	Categories []string `json:"categories"`
	// A list of the following for the type of risk documented:
	// - Confidentiality: Risk to data stores, customer/sensitive information, etc.
	// - Integrity: Risk to accuracy or integrity of system settings and/or data
	// - Availability: Risk to normal service operations and critical system functionality.
	CiaCategories []CIA `json:"ciaCategories"`
	// Indicate how your leadership team wants to address an identified risk. Please note: not all risks
	// need to be addressed immediately (or at all). Your Risk Treatment decision will depend on multiple
	// factors, such as your organization's risk tolerance and the value of the asset that the risk is
	// associated with. The options are:
	// - Mitigate: Identify controls to put in place or tasks to be done that will reduce the risk score.
	// - Transfer: Move risk outside of your organization's set of responsibilities e.g. get cyber
	// liability insurance.
	// - Avoid: Stop doing the activity which is causing the risk to your organization and its assets.
	// - Accept: Decide to live with the risk and take no further actions. - Accept: decide to live with
	// the risk; this may be because it is highly unlikely, has a low financial or operational impact, or
	// the cost and effort to treat the risk far exceeds the value of the asset.
	Treatment NilTreatment `json:"treatment"`
	// The email of the person responsible for tracking and mitigating this risk scenario.
	Owner NilString `json:"owner"`
	// Additional context about the risk scenario and why it has specific impact and likelihood scores.
	Note NilString `json:"note"`
	// Name of the risk register associated with this scenario.
	RiskRegister NilString `json:"riskRegister"`
	// The list of custom fields.
	// You can reference existing custom fields in the Risk Management settings and/or create new ones.
	// The format is:
	// - {label: "field-name", value: "string-representation"} for text, date, number and currency fields
	// - {label: "field-name", value: ["option1", "option2"]} for picklist fields.
	CustomFields []CustomAttribute `json:"customFields"`
	// Whether this scenario is archived.
	IsArchived bool `json:"isArchived"`
	// The current review status of this risk scenario.
	ReviewStatus ReviewStatus `json:"reviewStatus"`
	// The list of required approvers for this risk scenario.
	RequiredApprovers []string `json:"requiredApprovers"`
	// The type of risk scenario.
	// - "Risk Scenario": Standard risk scenario
	// - "Enterprise Risk": Enterprise-level risk.
	Type RiskScenarioType `json:"type"`
}

